DROP PROCEDURE IF EXISTS `sp_actualizar_complemento`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_actualizar_complemento` (IN `p_id_complemento` INT, IN `p_nombre` VARCHAR(100), IN `p_tipo` VARCHAR(50), IN `p_precio` DECIMAL(10,2), IN `p_activo` TINYINT(1))   BEGIN
  UPDATE complementos
     SET nombre = p_nombre,
         tipo   = p_tipo,
         precio = p_precio,
         activo = p_activo
   WHERE id_complemento = p_id_complemento;
END$$

DROP PROCEDURE IF EXISTS `sp_crear_complemento`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_crear_complemento` (IN `p_nombre` VARCHAR(100), IN `p_tipo` VARCHAR(50), IN `p_precio` DECIMAL(10,2), IN `p_activo` TINYINT(1))   BEGIN
  INSERT INTO complementos (nombre, tipo, precio, activo)
  VALUES (p_nombre, p_tipo, p_precio, p_activo);
END$$

DROP PROCEDURE IF EXISTS `sp_crear_plato`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_crear_plato` (IN `p_nombre` VARCHAR(255), IN `p_descripcion` TEXT, IN `p_precio` DECIMAL(10,2), IN `p_limite` INT, IN `p_imagen` MEDIUMBLOB, IN `p_activo` TINYINT, IN `p_usuario` VARCHAR(100))   BEGIN
    IF p_activo IS NULL THEN
        SET p_activo = 1;
    END IF;

    INSERT INTO platos 
      (nombre, descripcion, precio, limite_disponible, limite_inicial, imagen, activo)
    VALUES
      (p_nombre, p_descripcion, p_precio, p_limite, p_limite, p_imagen, p_activo);
END$$

DROP PROCEDURE IF EXISTS `sp_editar_plato`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_editar_plato` (IN `p_id` INT, IN `p_nombre` VARCHAR(255), IN `p_descripcion` TEXT, IN `p_precio` DECIMAL(10,2), IN `p_limite` INT, IN `p_imagen` MEDIUMBLOB, IN `p_activo` TINYINT, IN `p_usuario` VARCHAR(100))   BEGIN
    -- Si cambió el límite, restablecemos también el inicial:
    IF p_imagen IS NULL THEN
        UPDATE platos
           SET nombre            = p_nombre,
               descripcion       = p_descripcion,
               precio            = p_precio,
               limite_disponible = p_limite,
               limite_inicial    = p_limite,
               activo            = p_activo
         WHERE id_plato         = p_id;
    ELSE
        UPDATE platos
           SET nombre            = p_nombre,
               descripcion       = p_descripcion,
               precio            = p_precio,
               limite_disponible = p_limite,
               limite_inicial    = p_limite,
               imagen            = p_imagen,
               activo            = p_activo
         WHERE id_plato         = p_id;
    END IF;
END$$

DROP PROCEDURE IF EXISTS `sp_eliminar_complemento`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_eliminar_complemento` (IN `p_id_complemento` INT)   BEGIN
  DELETE FROM complementos
   WHERE id_complemento = p_id_complemento;
END$$

DROP PROCEDURE IF EXISTS `sp_eliminar_plato`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_eliminar_plato` (IN `p_id` INT, IN `p_usuario` VARCHAR(100))   BEGIN
  DECLARE v_nombre VARCHAR(255);

  -- Obtener el nombre del plato antes de borrarlo
  SELECT nombre
    INTO v_nombre
    FROM platos
   WHERE id_plato = p_id;

  -- Eliminar el plato
  DELETE FROM platos
   WHERE id_plato = p_id;
END$$

DROP PROCEDURE IF EXISTS `sp_leer_complemento`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_leer_complemento` (IN `p_id_complemento` INT)   BEGIN
  SELECT 
    id_complemento,
    nombre,
    tipo,
    precio,
    activo
  FROM complementos
  WHERE id_complemento = p_id_complemento;
END$$

DROP PROCEDURE IF EXISTS `sp_reiniciar_limite_plato`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_reiniciar_limite_plato` (IN `p_id_plato` INT)   BEGIN
  UPDATE platos
     SET limite_disponible = limite_inicial
   WHERE id_plato = p_id_plato;
END$$

DROP PROCEDURE IF EXISTS `sp_reiniciar_todos_limites`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_reiniciar_todos_limites` ()   BEGIN
  UPDATE platos
     SET limite_disponible = limite_inicial;
END$$

DROP PROCEDURE IF EXISTS `sp_reservar_plato`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_reservar_plato` (IN `p_id_plato` INT, IN `p_carnet_alumno` VARCHAR(20), IN `p_detalle` TEXT, IN `p_monto` DECIMAL(10,2))   BEGIN
  DECLARE v_limite INT;

  -- 1) Bloquea y lee el límite
  SELECT limite_disponible
    INTO v_limite
    FROM platos
   WHERE id_plato = p_id_plato
     FOR UPDATE;

  -- 2) Verifica stock
  IF v_limite <= 0 THEN
    SIGNAL SQLSTATE '45000' 
      SET MESSAGE_TEXT = 'No hay disponibilidad para este plato hoy';
  END IF;

  -- 3) Inserta pedido
  INSERT INTO pedidos (carnet_alumno, descripcion_pedido, fecha_reserva, id_plato)
  VALUES (p_carnet_alumno, p_detalle, CURDATE(), p_id_plato);

  SET @last = LAST_INSERT_ID();

  -- 4) Inserta línea principal
  INSERT INTO pedido_plato (id_pedido, id_plato, id_complemento, monto)
  VALUES (@last, p_id_plato, NULL, p_monto);

  -- 5) Decrementa límite
  UPDATE platos
     SET limite_disponible = v_limite - 1
   WHERE id_plato = p_id_plato;
END$$

