CREATE TRIGGER `trg_complementos_after_delete` AFTER DELETE ON `complementos` FOR EACH ROW BEGIN
  INSERT INTO historial(fecha, usuario, accion, detalle, nombre_tabla)
  VALUES(
    NOW(),
    @currentAdmin,
    'eliminar',
