DROP TRIGGER IF EXISTS `trg_pedidos_after_delete`;
DELIMITER $$
CREATE TRIGGER `trg_pedidos_after_delete` AFTER DELETE ON `pedidos` FOR EACH ROW BEGIN
  INSERT INTO historial (
    fecha,
    usuario,
    accion,
    detalle,
    nombre_tabla
  ) VALUES (
    NOW(),
    @usuario,
    'eliminar',
    CONCAT(
      'Eliminó pedido ID=', OLD.id_pedido,
      ' (Alumno=', OLD.carnet_alumno,
      ', Fecha=', DATE_FORMAT(OLD.fecha_reserva,'%Y-%m-%d'),
      ', PlatoID=', OLD.id_plato, ')'
    ),
    'pedidos'
  );
END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `trg_pedidos_after_insert`;
DELIMITER $$
CREATE TRIGGER `trg_pedidos_after_insert` AFTER INSERT ON `pedidos` FOR EACH ROW BEGIN
  INSERT INTO historial (
    fecha,
    usuario,
    accion,
    detalle,
    nombre_tabla
  ) VALUES (
    NOW(),
    @usuario,
    'crear',
    CONCAT(
      'Creó pedido: ',
      'Alumno=', NEW.carnet_alumno,
      ', Fecha=', DATE_FORMAT(NEW.fecha_reserva,'%Y-%m-%d'),
      ', PlatoID=', NEW.id_plato
    ),
    'pedidos'
  );
END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `trg_pedidos_after_update`;
DELIMITER $$
CREATE TRIGGER `trg_pedidos_after_update` AFTER UPDATE ON `pedidos` FOR EACH ROW BEGIN
  INSERT INTO historial (
    fecha,
    usuario,
    accion,
    detalle,
    nombre_tabla
  ) VALUES (
    NOW(),
    @usuario,
    'editar',
    CONCAT(
      'Editó pedido ID=', OLD.id_pedido,
      ' → Alumno=', NEW.carnet_alumno,
      ', Fecha=', DATE_FORMAT(NEW.fecha_reserva,'%Y-%m-%d'),
      ', PlatoID=', NEW.id_plato
    ),
    'pedidos'
  );
END
$$
DELIMITER ;

