--
-- Disparadores `platos`
--
DROP TRIGGER IF EXISTS `trg_platos_after_delete`;
DELIMITER $$
CREATE TRIGGER `trg_platos_after_delete` AFTER DELETE ON `platos` FOR EACH ROW BEGIN
  INSERT INTO historial (fecha, usuario, accion, detalle, nombre_tabla)
  VALUES (
    NOW(),
    @usuario,
    'eliminar',
    CONCAT('Eliminó plato: ', OLD.nombre),
    'platos'
  );
END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `trg_platos_after_insert`;
DELIMITER $$
CREATE TRIGGER `trg_platos_after_insert` AFTER INSERT ON `platos` FOR EACH ROW BEGIN
  INSERT INTO historial (fecha, usuario, accion, detalle, nombre_tabla)
  VALUES (
    NOW(),
    @usuario,
    'crear',
    CONCAT('Creó plato: ', NEW.nombre),
    'platos'
  );
END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `trg_platos_after_update`;
DELIMITER $$
CREATE TRIGGER `trg_platos_after_update` AFTER UPDATE ON `platos` FOR EACH ROW BEGIN
  IF NOT (OLD.activo <=> NEW.activo) THEN
    INSERT INTO historial (fecha, usuario, accion, detalle, nombre_tabla)
    VALUES (
      NOW(),
      @usuario,
      IF(NEW.activo=1,'habilitar','deshabilitar'),
      CONCAT(
        IF(NEW.activo=1,'Habilitó plato: ','Deshabilitó plato: '),
        NEW.nombre
      ),
      'platos'
    );
  ELSE
    INSERT INTO historial (fecha, usuario, accion, detalle, nombre_tabla)
    VALUES (
      NOW(),
      @usuario,
      'editar',
      CONCAT('Editó plato: ', NEW.nombre),
      'platos'
    );
  END IF;
END
$$
DELIMITER ;

